(() => {
  const SECTION_SELECTOR = "#bkg-video";
  const VIDEO_SELECTOR = "video.elementor-background-video-hosted";

  const section = document.querySelector(SECTION_SELECTOR);
  if (!section) return;

  const video = section.querySelector(VIDEO_SELECTOR);
  if (!video) return;

  const originalSrc = video.getAttribute("src");
  if (!originalSrc) return;

  // impede download imediato
  video.setAttribute("preload", "none");
  video.pause();
  video.removeAttribute("src");
  video.dataset.src = originalSrc;
  video.load(); // “limpa” o buffer

  const loadAndPlay = () => {
    if (video.dataset.loaded) return;
    video.dataset.loaded = "1";

    video.setAttribute("src", video.dataset.src);
    video.load();

    const p = video.play();
    if (p && typeof p.catch === "function") p.catch(() => {});

    section.classList.add("video-loaded");
  };

  if ("IntersectionObserver" in window) {
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          if (e.isIntersecting) {
            loadAndPlay();
            io.disconnect();
            break;
          }
        }
      },
      { rootMargin: "200px 0px" } // começa um pouco antes de aparecer
    );

    io.observe(section);
  } else {
    // fallback simples
    setTimeout(loadAndPlay, 800);
  }
})();
